            --stat-size: clamp(2rem, 5vw, 4.5rem);

            --slide-padding: clamp(1.5rem, 4vw, 4rem);
            --content-gap: clamp(0.75rem, 2vw, 1.5rem);
            --element-gap: clamp(0.25rem, 1vw, 0.75rem);

            --ease-out-expo: cubic-bezier(0.16, 1, 0.3, 1);
            --duration-normal: 0.6s;
        }

        /* ===========================================
           VIEWPORT FITTING: MANDATORY BASE STYLES
           =========================================== */
        html, body {
            height: 100%;
            overflow-x: hidden;
        }
        html {
            scroll-snap-type: y mandatory;
            scroll-behavior: smooth;
        }
        .slide {
            width: 100vw;
            height: 100vh;
            height: 100dvh;
            overflow: hidden;
            scroll-snap-align: start;
            display: flex;
            flex-direction: column;
            position: relative;
        }
        .slide-content {
            flex: 1;
            display: flex;
            flex-direction: column;
            justify-content: center;
            max-height: 100%;
            overflow: hidden;
            padding: var(--slide-padding);
        }
        .card, .container, .content-box {
            max-width: min(90vw, 1000px);
            max-height: min(80vh, 700px);
        }
        .feature-list, .bullet-list {
            gap: clamp(0.4rem, 1vh, 1rem);
        }
        .feature-list li, .bullet-list li {
            font-size: var(--body-size);
            line-height: 1.4;
        }
        .grid {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(min(100%, 250px), 1fr));
            gap: clamp(0.5rem, 1.5vw, 1rem);
        }
        img, .image-container {
            max-width: 100%;
            max-height: min(50vh, 400px);
            object-fit: contain;
        }
        @media (max-height: 700px) {
            :root {
                --slide-padding: clamp(0.75rem, 3vw, 2rem);
                --content-gap: clamp(0.4rem, 1.5vw, 1rem);
                --title-size: clamp(1.25rem, 4.5vw, 2.5rem);
                --h2-size: clamp(1rem, 3vw, 1.75rem);
            }
        }
        @media (max-height: 600px) {
            :root {
                --slide-padding: clamp(0.5rem, 2.5vw, 1.5rem);
                --content-gap: clamp(0.3rem, 1vw, 0.75rem);
                --title-size: clamp(1.1rem, 4vw, 2rem);
                --body-size: clamp(0.7rem, 1.2vw, 0.95rem);
            }
            .nav-dots, .keyboard-hint, .decorative { display: none; }
        }
        @media (max-height: 500px) {
            :root {
                --slide-padding: clamp(0.4rem, 2vw, 1rem);
                --title-size: clamp(1rem, 3.5vw, 1.5rem);
                --h2-size: clamp(0.9rem, 2.5vw, 1.25rem);
                --body-size: clamp(0.65rem, 1vw, 0.85rem);
            }
        }
        @media (max-width: 600px) {
            :root { --title-size: clamp(1.25rem, 7vw, 2.5rem); }
            .grid { grid-template-columns: 1fr; }
        }
        @media (prefers-reduced-motion: reduce) {
            *, *::before, *::after {
                animation-duration: 0.01ms !important;
                transition-duration: 0.2s !important;
            }
            html { scroll-behavior: auto; }
        }

        /* ===========================================
           RESET & BASE
           =========================================== */
        * { margin: 0; padding: 0; box-sizing: border-box; }
        body {
            font-family: var(--font-body);
            background: var(--bg-primary);
            color: var(--text-primary);
            -webkit-font-smoothing: antialiased;
        }

        /* ===========================================
           BACKGROUND GRID PATTERN
           =========================================== */
        .slide::before {
            content: '';
            position: absolute;
            inset: 0;
            background-image:
                linear-gradient(rgba(0, 212, 170, 0.03) 1px, transparent 1px),
                linear-gradient(90deg, rgba(0, 212, 170, 0.03) 1px, transparent 1px);
            background-size: 60px 60px;
            pointer-events: none;
            z-index: 0;
        }

        /* ===========================================
           TYPOGRAPHY
           =========================================== */
        h1, h2, h3 { font-family: var(--font-display); font-weight: 600; }
        h1 { font-size: var(--title-size); line-height: 1.1; }
        h2 { font-size: var(--h2-size); line-height: 1.15; }
        h3 { font-size: var(--h3-size); line-height: 1.2; }
        p, li { font-size: var(--body-size); line-height: 1.5; }

        /* ===========================================
           SLIDE-SPECIFIC STYLES
           =========================================== */

        /* --- Title Slide --- */
        .title-slide {
            background:
                radial-gradient(ellipse at 20% 80%, rgba(0, 212, 170, 0.08) 0%, transparent 50%),
                radial-gradient(ellipse at 80% 20%, rgba(74, 144, 217, 0.06) 0%, transparent 50%),
                var(--bg-primary);
            justify-content: center;
            align-items: flex-start;
            padding: var(--slide-padding);
        }
        .title-slide .slide-inner {
            position: relative;
            z-index: 1;
            max-width: 85%;
        }
        .title-tag {
            display: inline-block;
            font-family: var(--font-body);
            font-size: var(--small-size);
            font-weight: 500;
            letter-spacing: 0.15em;
            text-transform: uppercase;
            color: var(--accent-teal);
            border: 1px solid var(--accent-teal);
            padding: clamp(0.2rem, 0.5vw, 0.4rem) clamp(0.5rem, 1vw, 0.8rem);
            border-radius: 3px;
            margin-bottom: var(--content-gap);
        }
        .title-sub {
            font-family: var(--font-body);
            font-size: var(--h3-size);
            color: var(--text-secondary);
            margin-top: var(--content-gap);
            font-weight: 400;
            max-width: 700px;
        }
        .title-range {
            font-family: var(--font-body);
            font-size: var(--body-size);
            color: var(--text-muted);
            margin-top: var(--element-gap);
        }
        .title-range span {
            color: var(--accent-amber);
            font-weight: 500;
        }

        /* --- Section Number Badge --- */
        .section-num {
            font-family: var(--font-display);
            font-size: clamp(0.6rem, 1vw, 0.75rem);
            font-weight: 600;
            color: var(--accent-teal);
            letter-spacing: 0.1em;
            text-transform: uppercase;
            margin-bottom: clamp(0.25rem, 0.5vw, 0.5rem);
        }

        /* --- Chart Container --- */
        .chart-wrap {
            position: relative;
            width: 100%;
            max-height: min(55vh, 420px);
            margin: var(--element-gap) 0;
        }
        .chart-wrap svg {
            width: 100%;
            height: 100%;
            max-height: min(55vh, 420px);
        }

        /* --- Stat Card --- */
        .stat-card {
            background: var(--bg-card);
            border: 1px solid var(--border-subtle);
            border-radius: 8px;
            padding: clamp(0.75rem, 2vw, 1.5rem);
        }
        .stat-big {
            font-family: var(--font-display);
            font-size: var(--stat-size);
            font-weight: 700;
            line-height: 1;
        }
        .stat-label {
            font-size: var(--small-size);
            color: var(--text-secondary);
            margin-top: clamp(0.15rem, 0.3vw, 0.3rem);
            text-transform: uppercase;
            letter-spacing: 0.05em;
        }
        .stat-delta {
            font-size: var(--small-size);
            margin-top: clamp(0.1rem, 0.2vw, 0.2rem);
            font-weight: 500;
        }
        .stat-delta.up { color: var(--accent-amber); }
        .stat-delta.down { color: var(--accent-teal); }

        /* --- Split Layout --- */
        .split-layout {
            display: grid;
            grid-template-columns: 1fr 1.5fr;
            gap: clamp(1rem, 2vw, 2rem);
            align-items: start;
            flex: 1;
            min-height: 0;
        }

        /* --- Legend --- */
        .legend {
            display: flex;
            gap: clamp(0.75rem, 2vw, 1.5rem);
            margin-top: clamp(0.25rem, 0.5vw, 0.5rem);
        }
        .legend-item {
            display: flex;
            align-items: center;
            gap: clamp(0.25rem, 0.5vw, 0.4rem);
            font-size: var(--small-size);
            color: var(--text-secondary);
        }
        .legend-dot {
            width: clamp(8px, 1vw, 10px);
            height: clamp(8px, 1vw, 10px);
            border-radius: 50%;
        }

        /* --- HTTPS Big Callout --- */
        .https-callout {
            display: flex;
            align-items: center;
            gap: clamp(1rem, 3vw, 3rem);
            flex: 1;
            min-height: 0;
        }
        .https-stat-side {
            flex: 0 0 auto;
            text-align: center;
        }
        .https-chart-side {
            flex: 1;
            min-height: 0;
        }
        .https-chart-side .chart-wrap {
            max-height: min(35vh, 280px);
        }

        /* --- Protocol Bars --- */
        .proto-grid {
            display: grid;
            grid-template-columns: 1fr 1fr;
            gap: clamp(0.75rem, 1.5vw, 1.25rem);
        }
        .proto-card {
            background: var(--bg-card);
            border: 1px solid var(--border-subtle);
            border-radius: 8px;
            padding: clamp(0.75rem, 2vw, 1.5rem);
        }
        .proto-value {
            font-family: var(--font-display);
            font-size: clamp(1.5rem, 4vw, 3rem);
            font-weight: 700;
            line-height: 1;
        }
        .proto-label {
            font-size: var(--small-size);
            color: var(--text-secondary);
            margin-top: clamp(0.2rem, 0.4vw, 0.3rem);
        }
        .proto-delta {
            font-size: var(--small-size);
            margin-top: clamp(0.15rem, 0.3vw, 0.2rem);
            font-weight: 500;
        }
        .bar-track {
            height: clamp(4px, 0.6vw, 6px);
            background: var(--border-subtle);
            border-radius: 3px;
            margin-top: clamp(0.4rem, 0.8vw, 0.6rem);
            overflow: hidden;
        }
        .bar-fill {
            height: 100%;
            border-radius: 3px;
            transition: width 1s var(--ease-out-expo);
        }

        /* --- Takeaway Bullets --- */
        .takeaway-list {
            list-style: none;
            display: flex;
            flex-direction: column;
            gap: clamp(0.5rem, 1.2vh, 1rem);
        }
        .takeaway-item {
            display: flex;
            align-items: flex-start;
            gap: clamp(0.5rem, 1vw, 0.75rem);
            font-size: var(--body-size);
            line-height: 1.45;
        }
        .takeaway-num {
            font-family: var(--font-display);
            font-weight: 700;
            color: var(--accent-teal);
            font-size: var(--h3-size);
            flex-shrink: 0;
            min-width: clamp(1.2rem, 2vw, 1.8rem);
        }
        .cta-box {
            margin-top: clamp(0.5rem, 1.5vh, 1.25rem);
            padding: clamp(0.5rem, 1vw, 0.75rem) clamp(0.75rem, 1.5vw, 1rem);
            background: var(--accent-teal-dim);
            border-left: 3px solid var(--accent-teal);
            border-radius: 0 4px 4px 0;
            font-size: var(--body-size);
            font-weight: 500;
            color: var(--accent-teal);
        }

        /* --- SVG Chart Styles --- */
        .chart-axis { stroke: var(--border-subtle); stroke-width: 1; }
        .chart-axis-label {
            fill: var(--text-muted);
            font-family: var(--font-body);
            font-size: 10px;
        }
        .chart-grid-line { stroke: var(--border-subtle); stroke-width: 0.5; stroke-dasharray: 4 4; }
        .chart-line-desktop {
            fill: none;
            stroke: var(--accent-teal);
            stroke-width: 2.5;
            stroke-linecap: round;
            stroke-linejoin: round;
        }
        .chart-line-mobile {
            fill: none;
            stroke: var(--accent-blue);
            stroke-width: 2.5;
            stroke-linecap: round;
            stroke-linejoin: round;
        }
        .chart-line-single {
            fill: none;
            stroke: var(--accent-teal);
            stroke-width: 2.5;
            stroke-linecap: round;
            stroke-linejoin: round;
        }
        .chart-band-desktop {
            fill: var(--accent-teal-dim);
            stroke: none;
        }
        .chart-band-mobile {
            fill: var(--accent-blue-dim);
            stroke: none;
        }
        .chart-dot {
            r: 3;
            stroke-width: 2;
        }
        .chart-annotation {
            fill: var(--text-secondary);
            font-family: var(--font-body);
            font-size: 10px;
        }

        /* --- Font-display bar --- */
        .fd-bar-wrap {
            margin-top: clamp(0.5rem, 1vw, 0.75rem);
        }
        .fd-bar-label {
            display: flex;
            justify-content: space-between;
            font-size: var(--small-size);
            margin-bottom: clamp(0.15rem, 0.3vw, 0.2rem);
        }
        .fd-bar-label span:first-child { color: var(--text-secondary); }
        .fd-bar-label span:last-child { font-weight: 600; }
        .fd-bar-track {
            height: clamp(6px, 0.8vw, 8px);
            background: var(--border-subtle);
            border-radius: 4px;
            overflow: hidden;
            margin-bottom: clamp(0.4rem, 0.8vw, 0.6rem);
        }
        .fd-bar-fill {
            height: 100%;
            border-radius: 4px;
            transition: width 1.2s var(--ease-out-expo);
        }

        /* ===========================================
           ANIMATIONS
           =========================================== */
        .reveal {
            opacity: 0;
            transform: translateY(25px);
            transition: opacity var(--duration-normal) var(--ease-out-expo),
                        transform var(--duration-normal) var(--ease-out-expo);
        }
        .slide.visible .reveal {
            opacity: 1;
            transform: translateY(0);
        }
        .reveal:nth-child(1) { transition-delay: 0.05s; }
        .reveal:nth-child(2) { transition-delay: 0.15s; }
        .reveal:nth-child(3) { transition-delay: 0.25s; }
        .reveal:nth-child(4) { transition-delay: 0.35s; }
        .reveal:nth-child(5) { transition-delay: 0.45s; }
        .reveal:nth-child(6) { transition-delay: 0.55s; }

        /* Accent line animation */
        .accent-line {
            width: 0;
            height: 3px;
            background: var(--accent-teal);
            margin-top: clamp(0.5rem, 1vw, 0.75rem);
            margin-bottom: clamp(0.5rem, 1vw, 0.75rem);
            transition: width 0.8s var(--ease-out-expo);
        }
        .slide.visible .accent-line {
            width: clamp(40px, 8vw, 80px);
        }

        /* ===========================================
           PROGRESS BAR
           =========================================== */
        .progress-bar {
            position: fixed;
            top: 0;
            left: 0;
            height: 3px;
            background: var(--accent-teal);
            z-index: 1000;
            transition: width 0.3s ease;
        }

        /* ===========================================
           NAV DOTS
           =========================================== */
        .nav-dots {
            position: fixed;
            right: clamp(10px, 1.5vw, 20px);
            top: 50%;
            transform: translateY(-50%);
            display: flex;
            flex-direction: column;
            gap: 8px;
            z-index: 999;
        }
        .nav-dot {
            width: 8px;
            height: 8px;
            border-radius: 50%;
            background: var(--border-subtle);
            cursor: pointer;
            transition: background 0.3s ease, transform 0.3s ease;
        }
        .nav-dot.active {
            background: var(--accent-teal);
            transform: scale(1.3);
        }
    </style>
</head>
