    const page = await browser.newPage();
    await page.setViewportSize({ width: 1920, height: 1080 });
    await page.goto(url, { waitUntil: 'networkidle' });

    // Force all slides to be visible (override reveal animations)
    await page.evaluate(() => {
        document.querySelectorAll('.slide').forEach(s => s.classList.add('visible'));
        document.querySelectorAll('.reveal').forEach(el => {
            el.style.opacity = '1';
            el.style.transform = 'none';
        });
        document.querySelectorAll('.accent-line').forEach(el => {
            el.style.width = '80px';
        });
    });

    // Wait for fonts and rendering
    await page.waitForTimeout(2000);

    const slideCount = await page.$$('.slide').then(els => els.length);
    console.log('Found ' + slideCount + ' slides');

    // Capture each slide by scrolling into view
    for (let i = 0; i < slideCount; i++) {
        await page.evaluate((idx) => {
            const slides = document.querySelectorAll('.slide');
            if (slides[idx]) slides[idx].scrollIntoView();
        }, i);
        await page.waitForTimeout(600);
        await page.screenshot({ path: '/tmp/slide_' + String(i).padStart(3, '0') + '.png' });
    }

    await browser.close();
})();
